const D = { wear: .45, scale: 1, energy: .6, density: .5, hue: 24, speed: 1, x: .28, y: .5, alpha: 1, style: 'full_grain', act: 'flex', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height;
const sty=P.style, act=P.act;
const wear=cl(P.wear,0,1.4), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

// ---- follicle jitter lattice, built once per seed (never hash inside the pixel loop) ----
const LP=64;
if(S.jK!==P.seed || !S.jt){ S.jK=P.seed; const J=new Float32Array(LP*LP*2);
  for(let k=0;k<LP*LP;k++){ J[k*2]=(fr(k*1.73+900)-.5)*.86; J[k*2+1]=(fr(k*1.73+901)-.5)*.86; }
  S.jt=J; }
const JT=S.jt;

const BW=190, BH=cl(Math.round(BW*Hh/Math.max(1,W)),56,190);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; S.h=new Float32Array(BW*BH); S.wv=new Float32Array(BW*BH); }
const G=S.g, HF=S.h, WV=S.wv;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let flexAmp, ageF, stretch;
if(act==='age'){ flexAmp=.55; ageF=.55+.75*(.5+.5*Math.sin(sec*.8+T*.017)); stretch=1; }
else if(act==='stretch'){ flexAmp=.5; ageF=1; stretch=1+.30*Math.sin(sec*.9+T*.023); }
else { flexAmp=1; ageF=1; stretch=1; }

// ---- the hide flexes: two travelling bend waves at incommensurate speeds. The phase
// only ever advances, so the grain is always working and the motion floor cannot
// re-phase away. Where the hide folds shut the creases deepen and the pebbles crowd.
const fp1=.115*TD, fp2=.071*TD;
// raking light — the burnished high points are what glint
const lAz=cl(P.x,0,1)*TAU + .0120*TD + .23*Math.sin(TD*.045+.5) + .11*Math.sin(TD*.101+2.3);
const lx=Math.cos(lAz), ly=Math.sin(lAz);
const lEl=(cl(P.y,0,1)-.5)*1.25 + .13*Math.sin(TD*.059+1.2) + .06*Math.sin(TD*.127+2.7) + .03*K.swell;

// ---- style ----
let HIDE, CORIUM, CREASE, spTint, cast=0, nap=0, glossK=1, burnK=1;
if(sty==='distressed'){ HIDE=hsb2rgb(H+2,52,47); CORIUM=hsb2rgb(H+8,38,78); CREASE=hsb2rgb(H-6,60,12); spTint=[255,240,214]; glossK=.85; burnK=1.5; }
else if(sty==='patent'){ HIDE=hsb2rgb(H,46,26); CORIUM=hsb2rgb(H,40,42); CREASE=hsb2rgb(H,50,8); spTint=[255,255,255]; glossK=3.0; burnK=.5; }
else if(sty==='suede'){ HIDE=hsb2rgb(H-4,30,54); CORIUM=hsb2rgb(H-2,24,68); CREASE=hsb2rgb(H-8,34,28); spTint=[240,232,214]; glossK=.16; burnK=.25; nap=1; }
else if(sty==='cast'){ HIDE=hsb2rgb(H+6,5,58); CORIUM=hsb2rgb(H+6,4,66); CREASE=hsb2rgb(H+6,7,26); spTint=[255,253,248]; cast=1; glossK=.7; burnK=.5; }
else { HIDE=hsb2rgb(H,50,52); CORIUM=hsb2rgb(H+8,40,74); CREASE=hsb2rgb(H-8,62,14); spTint=[255,238,206]; glossK=1; burnK=1; }

const asp=W/Math.max(1,Hh);
const camX=.009*Math.sin(TD*.041+.9), camY=.009*Math.cos(TD*.055+2.1);
const pf=(24+dens*30)/Math.max(.35,sc);     // follicle cells across the hide
const wf=1.5/Math.max(.35,sc);
const creaseD=.30+.34*dens;
const pebbleH=.020+.016*dens;

// ---- PASS 1: grain topography + the wear field ----
for(let j=0;j<BH;j++){
  const sy0=(j/BH-.5)+camY;
  for(let i=0;i<BW;i++){
    const sx0=(i/BW-.5)*asp+camX;
    // the bend field: >0 where the hide is folding shut
    const flex=(Math.sin(sx0*2.1+sy0*.7-fp1)*.55+Math.sin(sx0*1.3-sy0*1.9-fp2+1.7)*.35)*flexAmp;
    // the grain stretches and crowds with the bend — this is what actually moves
    const st=(1+.085*flex)*stretch;
    const gx=sx0*pf*st, gy=sy0*pf*st;
    const ci=Math.floor(gx), cj=Math.floor(gy);
    let f1=9e9, f2=9e9;
    for(let a=-1;a<=1;a++) for(let b=-1;b<=1;b++){
      const cx=ci+a, cy=cj+b;
      const ji=(md(cy,LP)*LP+md(cx,LP))*2;
      const dx=gx-(cx+.5+JT[ji]), dy=gy-(cy+.5+JT[ji+1]);
      const d=Math.sqrt(dx*dx+dy*dy);
      if(d<f1){ f2=f1; f1=d; } else if(d<f2){ f2=d; }
    }
    const edge=f2-f1;                                  // ~0 along the follicle borders
    const ew=.16+.10*dens;
    let peb=cl(edge/ew,0,1); peb=peb*peb*(3-2*peb);    // domed in the cell, sunk at the border
    // the coarse wrinkle network the hide has taken from a lifetime of flexing
    const w1=nzAt(sx0*wf+5.1, sy0*wf+2.7), w2=nzAt(sx0*wf*2.3-3.3, sy0*wf*2.3+8.8);
    const rid=1-Math.abs((w1*.7+w2*.3)-.5)*2.6;
    const wrink=cl(rid,0,1)*(1+.85*flex);              // creases bite deeper as it folds shut
    // wear: where the finish has been rubbed off the high points
    const wf2=nzAt(sx0*.9+31.1, sy0*.9+17.7)*.7+nzAt(sx0*3.7-9.9, sy0*3.7+4.4)*.4;
    const abr=cl((wf2-(.70-.30*wear))*2.4,0,1)*cl(wear*1.15,0,1.4)*ageF;
    const h=peb*pebbleH - wrink*wrink*creaseD*.055 + flex*.010;
    HF[j*BW+i]=h;
    WV[j*BW+i]=abr+peb*.0001;
    // stash the pebble/crease terms in the pixel buffer's alpha-free slots via HF/WV only
  }
}

// ---- PASS 2: shade off the grain topography ----
G.loadPixels();
const px=G.pixels, sR=spTint[0], sG=spTint[1], sB=spTint[2];
const NG=46;
const spAmt=(.16+.80*en)*glossK*(.6+.6*K.intensity)+S.tre*.22*en;
for(let j=0;j<BH;j++){
  const j0=Math.max(0,j-1)*BW, j1=Math.min(BH-1,j+1)*BW, jr=j*BW;
  const sy0=(j/BH-.5)+camY;
  for(let i=0;i<BW;i++){
    const idx=jr+i, o=idx*4;
    const sx0=(i/BW-.5)*asp+camX;
    const nx=-(HF[jr+Math.min(BW-1,i+1)]-HF[jr+Math.max(0,i-1)])*.5*NG;
    const ny=-(HF[j1+i]-HF[j0+i])*.5*NG;
    const nl=1/Math.sqrt(nx*nx+ny*ny+1);
    const Nx=nx*nl, Ny=ny*nl, Nz=nl;
    const hgt=HF[idx], abr=WV[idx];
    // how high does this sit in the grain? high points get burnished, creases hold dye
    const hi=cl((hgt+.013)/.036,0,1);
    let R,Gc,B;
    if(cast){ // form from light only — a plaster cast of the grain, no colour at all
      const lam=cl(.42+(Nx*lx+Ny*ly)*.95+Nz*.16,.08,1.5);
      R=HIDE[0]*lam; Gc=HIDE[1]*lam; B=HIDE[2]*lam;
    } else {
      // dye pools in the creases and gets rubbed off the crowns
      const t=Math.pow(hi,.85);
      R=CREASE[0]+(HIDE[0]-CREASE[0])*t; Gc=CREASE[1]+(HIDE[1]-CREASE[1])*t; B=CREASE[2]+(HIDE[2]-CREASE[2])*t;
      // burnish: long use polishes and darkens the crowns
      const bn=cl((hi-.55)*2.2,0,1)*burnK*(.35+.5*wear);
      R*=(1-bn*.22); Gc*=(1-bn*.24); B*=(1-bn*.26);
      // abrasion pulls the finish back to the pale corium under it
      const aw=cl(abr*(.45+.7*hi),0,1);
      R=R+(CORIUM[0]-R)*aw; Gc=Gc+(CORIUM[1]-Gc)*aw; B=B+(CORIUM[2]-B)*aw;
      const lam=cl(.44+(Nx*lx+Ny*ly)*.80+Nz*.14,.16,1.5);
      R*=(.52+.66*lam); Gc*=(.52+.66*lam); B*=(.52+.66*lam);
    }
    // specular: only the burnished crowns really glint; suede scatters instead
    const hn=cl(Nx*lx+Ny*ly-lEl*.5,-3,3);
    let spec;
    if(nap){ // napped fibres — a soft directional scatter, not a glint
      const napd=nzAt(sx0*70+11.1, sy0*70+3.3);
      spec=spAmt*(.35+.5*napd)*cl(.5+(Nx*lx+Ny*ly)*.8,0,1);
    } else {
      spec=spAmt*(.20+1.5*cl((hi-.5)*2,0,1)*(cast?.5:1))/(1+hn*hn*11);
    }
    const s2=spec*(cast?52:66);
    R+=sR*s2/255; Gc+=sG*s2/255; B+=sB*s2/255;
    const vx=(i/BW-.5), vy=(j/BH-.5), vg=1-.30*(vx*vx*1.1+vy*vy*1.5);
    R*=vg; Gc*=vg; B*=vg;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);
